steps.run:
set -eu
export PATH="$HOME/.local/bin:$PATH"
command -v git >/dev/null 2>&1 || { printf "%s\n" "Install Git using your server package manager first." >&2; exit 1; }
case "$(uname -s)-$(uname -m)" in
  Linux-x86_64|Linux-amd64) git_asset="lazygit_0.65.1_linux_x86_64.tar.gz"; git_sha="02beacbcda0fa342e50ae3480ba8147307353af3fb28e1d5f790e02329c201a6" ;;
  Linux-aarch64|Linux-arm64) git_asset="lazygit_0.65.1_linux_arm64.tar.gz"; git_sha="49abecdf6adf4f2dfdb11bf7b9bfada267ea523612ed809d1c6d87f6c04000a7" ;;
  Darwin-x86_64) git_asset="lazygit_0.65.1_darwin_x86_64.tar.gz"; git_sha="fde13daf583511aa24c42ca154911643231a5af784c7cdd8117264b2fc035b33" ;;
  Darwin-arm64) git_asset="lazygit_0.65.1_darwin_arm64.tar.gz"; git_sha="65a367c6ea9a88efebaaf7998a6835eedb987e04916cef677264ff9b31b1b13e" ;;
  *) printf "%s\n" "No pinned lazygit build for this OS/architecture. Install it using the server package manager." >&2; exit 1 ;;
esac
command -v curl >/dev/null 2>&1 || { printf "%s\n" "curl is required." >&2; exit 1; }
command -v tar >/dev/null 2>&1 || { printf "%s\n" "tar is required." >&2; exit 1; }
if command -v sha256sum >/dev/null 2>&1; then git_hash_tool=sha256sum; elif command -v shasum >/dev/null 2>&1; then git_hash_tool=shasum; else printf "%s\n" "sha256sum or shasum is required." >&2; exit 1; fi
git_setup_tmp=$(mktemp -d "${TMPDIR:-/tmp}/mobile-ssh-git.XXXXXX")
trap 'rm -rf "$git_setup_tmp"' 0
trap 'exit 1' HUP INT TERM
curl --fail --silent --show-error --location --proto "=https" --proto-redir "=https" --connect-timeout 20 --max-time 180 "https://github.com/jesseduffield/lazygit/releases/download/v0.65.1/$git_asset" -o "$git_setup_tmp/archive.tar.gz"
if [ "$git_hash_tool" = sha256sum ]; then git_actual=$(sha256sum "$git_setup_tmp/archive.tar.gz"); else git_actual=$(shasum -a 256 "$git_setup_tmp/archive.tar.gz"); fi
git_actual=${git_actual%% *}
[ "$git_actual" = "$git_sha" ] || { printf "%s\n" "SHA-256 mismatch; nothing installed." >&2; exit 1; }
tar -xzf "$git_setup_tmp/archive.tar.gz" -C "$git_setup_tmp"
git_binary="$git_setup_tmp/lazygit"
"$git_binary" --version
mkdir -p "$HOME/.local/bin"
git_install_tmp=$(mktemp "$HOME/.local/bin/.mobile-ssh-lazygit.XXXXXX")
trap 'rm -rf "$git_setup_tmp"; rm -f "$git_install_tmp"' 0
cat "$git_binary" > "$git_install_tmp"
chmod 755 "$git_install_tmp"
mv -f "$git_install_tmp" "$HOME/.local/bin/lazygit"
"$HOME/.local/bin/lazygit" --version

